import{_ as l,a0 as p,w as r,s as c,ao as o,I as t,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"screen 命令使用及示例 | LCTT x X-CMD","titleTemplate":false,"description":"screen 命令使用及示例 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"screen 命令使用及示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"screen 命令使用及示例 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170210 Basic screen command usage and examples","title":"screen 命令使用及示例","tag":"201702","desc":""},"relativePath":"201702/20170210 Basic screen command usage and examples.md","filePath":"[post].md"}'),d={name:"201702/20170210 Basic screen command usage and examples.md"};function h(g,s,k,b,u,m){const a=p("Link");return r(),c("div",null,[s[13]||(s[13]=o(`<h1 id="screen-命令使用及示例" tabindex="-1">screen 命令使用及示例 <a class="header-anchor" href="#screen-命令使用及示例" aria-label="Permalink to “screen 命令使用及示例”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/linux-screen-usage-examples.jpg" alt="linux screen command usage and examples"></p><p><code>screen</code> 是一個非常有用的命令，提供從單個 SSH 會話中使用多個 shell 窗口（會話）的能力。當會話被分離或網絡中斷時，screen 會話中啓動的進程仍將運行，你可以隨時重新連接到 screen 會話。如果你想運行一個持久的進程或者從多個位置連接到 shell 會話，這也很方便。</p><p>在本文中，我們將展示在 Linux 上安裝和使用 <code>screen</code> 的基本知識。</p><h3 id="如何安裝-screen" tabindex="-1">如何安裝 screen <a class="header-anchor" href="#如何安裝-screen" aria-label="Permalink to “如何安裝 screen”">​</a></h3><p><code>screen</code> 在一些流行的發行版上已經預安裝了。你可以使用下面的命令檢查是否已經在你的服務器上安裝了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -v</span></span>
<span class="line"><span>Screen version 4.00.03 (FAU)</span></span></code></pre></div><p>如果在 Linux 中還沒有 <code>screen</code>，你可以使用系統提供的包管理器很簡單地安裝它。</p><p><strong>CentOS/RedHat/Fedora</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum -y install screen</span></span></code></pre></div><p><strong>Ubuntu/Debian</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get -y install screen</span></span></code></pre></div><h3 id="如何啓動一個-screen-會話" tabindex="-1">如何啓動一個 screen 會話 <a class="header-anchor" href="#如何啓動一個-screen-會話" aria-label="Permalink to “如何啓動一個 screen 會話”">​</a></h3><p>你可以在命令列中輸入 <code>screen</code> 來啓動它，接着會有一個看上去和命令列提示符一樣的 <code>screen</code> 會話啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen</span></span></code></pre></div><p>使用描述性名稱啓動屏幕會話是一個很好的做法，這樣你可以輕鬆地記住會話中正在運行的進程。要使用會話名稱創建新會話，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -S name</span></span></code></pre></div><p>將 “name” 替換為對你會話有意義的名字。</p><h3 id="從-screen-會話中分離" tabindex="-1">從 screen 會話中分離 <a class="header-anchor" href="#從-screen-會話中分離" aria-label="Permalink to “從 screen 會話中分離”">​</a></h3><p>要從當前的 screen 會話中分離，你可以按下 <code>Ctrl-A</code> 和 <code>d</code>。所有的 screen 會話仍將是活躍的，你之後可以隨時重新連接。</p><h3 id="重新連接到-screen-會話" tabindex="-1">重新連接到 screen 會話 <a class="header-anchor" href="#重新連接到-screen-會話" aria-label="Permalink to “重新連接到 screen 會話”">​</a></h3><p>如果你從一個會話分離，或者由於某些原因你的連接被中斷了，你可以使用下面的命令重新連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r</span></span></code></pre></div><p>如果你有多個 screen 會話，你可以用 <code>ls</code> 參數列出它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -ls</span></span>
<span class="line"><span></span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>7880.session    (Detached)</span></span>
<span class="line"><span>7934.session2   (Detached)</span></span>
<span class="line"><span>7907.session1   (Detached)</span></span>
<span class="line"><span>3 Sockets in /var/run/screen/S-root.</span></span></code></pre></div><p>在我們的例子中，我們有三個活躍的 screen 會話。因此，如果你想要還原 “session2” 會話，你可以執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r 7934</span></span></code></pre></div><p>或者使用 screen 名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r -S session2</span></span></code></pre></div><h3 id="中止-screen-會話" tabindex="-1">中止 screen 會話 <a class="header-anchor" href="#中止-screen-會話" aria-label="Permalink to “中止 screen 會話”">​</a></h3><p>有幾種方法來中止 screen 會話。你可以按下 <code>Ctrl+d</code>，或者在命令列中使用 <code>exit</code> 命令。</p><p>要查看 <code>screen</code> 命令所有有用的功能，你可以查看 <code>screen</code> 的 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man screen</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NAME</span></span>
<span class="line"><span>screen - screen manager with VT100/ANSI terminal emulation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SYNOPSIS</span></span>
<span class="line"><span>screen [ -options ] [ cmd [ args ] ]</span></span>
<span class="line"><span>screen -r [[pid.]tty[.host]]</span></span>
<span class="line"><span>screen -r sessionowner/[[pid.]tty[.host]]</span></span></code></pre></div><hr><p>順便説一下，如果你喜歡這篇文章，請在社交網絡上與你的朋友分享，或者在評論區留下評論。謝謝。</p><hr>`,36)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),n(a,{href:"https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/"},{default:i(()=>[...s[2]||(s[2]=[e("rosehosting.com",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[3]||(s[3]=[e("geekpi",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),n(a,{href:"https://github.com/jasminepeng"},{default:i(()=>[...s[4]||(s[4]=[e("jasminepeng",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const y=l(d,[["render",h]]);export{C as __pageData,y as default};
